alue": "Updated procedure to calculate average of integer arrays"} ]' Response{ "id": "d02b24fa-a246-4563-adf1-9ad21f251c0e", "name": "calculate_average", "fullyQualifiedName": "sample_data.ecommerce_db.shopify.calculate_average", "description": "Updated procedure to calculate average of integer arrays", "storedProcedureCode": { "code": "CREATE OR REPLACE PROCEDURE calculate_average(numbers INT ARRAY) RETURNS FLOAT NOT NULL LANGUAGE SQL AS $$DECLARE sum_val INT = 0;count_val INT = 0;average_val FLOAT;BEGIN
 FOR num IN ARRAY numbers DO sum_val := sum_val + num;
